
const mongoose = require("mongoose");

const deviceSchema = new mongoose.Schema(
  {
    // Unique identifier generated by the mobile app
    deviceId: {
      type: String,
      required: [true, "Device ID is required"],
      unique: true,
      trim: true,
      index: true
    },

    // Friendly name of the monitoring device
    deviceName: {
      type: String,
      trim: true,
      default: "Android Monitor"
    },

    // Device registration status
    status: {
      type: String,
      enum: ["active", "inactive", "revoked"],
      default: "active"
    },

    registeredAt: {
      type: Date,
      default: Date.now
    }
  },
  {
    timestamps: true,
    versionKey: false
  }
);

const Device = mongoose.model("Device", deviceSchema);

module.exports = Device;
